<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
expire_pickup_reservations((int)$user['id']);expire_unpaid_delivery_requests((int)$user['id']);activate_estimated_deliveries((int)$user['id']);
$borrowings=rows('SELECT b.*,k.title,k.book_id FROM borrowings b JOIN books k ON k.id=b.book_id WHERE b.user_id=? AND b.history_visible=1 ORDER BY b.created_at DESC',[$user['id']]);$complaints=rows('SELECT c.*,k.title,k.book_id FROM complaints c JOIN books k ON k.id=c.book_id WHERE c.user_id=? ORDER BY c.created_at DESC',[$user['id']]);$reviews=rows('SELECT r.*,k.title,k.book_id FROM reviews r JOIN books k ON k.id=r.book_id WHERE r.user_id=? ORDER BY r.created_at DESC',[$user['id']]);$extensions=rows('SELECT e.*,k.title FROM extensions e JOIN borrowings br ON br.id=e.borrowing_id JOIN books k ON k.id=br.book_id WHERE e.user_id=? ORDER BY e.requested_at DESC',[$user['id']]);member_start('Riwayat Anggota',$user,'Riwayat.php'); ?>
<section class="member-section"><span class="member-kicker">AKTIVITAS ANGGOTA</span><h1>Riwayat</h1><h2>Peminjaman buku</h2><div class="member-table-wrap"><table><thead><tr><th>Buku</th><th>Mulai pinjam</th><th>Batas pengembalian / proses</th><th>Dikembalikan</th><th>Status</th></tr></thead><tbody><?php foreach($borrowings as $b):?><tr><td><?=e($b['title'])?> <small>(<?=e($b['book_id'])?>)</small></td><td><?php if($b['status']==='in_transit'):?>Menunggu konfirmasi kurir<?php elseif($b['status']==='pickup_pending'):?>Menunggu konfirmasi admin<?php elseif($b['status']==='awaiting_payment'):?>Menunggu pembayaran<?php elseif(in_array($b['status'],['active','overdue','returned'],true)):?><?=date_id($b['borrowed_at'],true)?><?php else:?>—<?php endif;?></td><td><?php if($b['status']==='pickup_pending'):?>Ambil sebelum <?=date_id($b['pickup_deadline'],true)?><?php elseif($b['status']==='awaiting_payment'):?>Bayar sebelum <?=date_id($b['payment_deadline'],true)?><?php elseif($b['status']==='in_transit'):?>Estimasi sampai <?=date_id($b['estimated_delivery'],true)?><?php elseif(in_array($b['status'],['active','overdue','returned'],true)):?><?=date_id($b['due_date'],true)?><?php else:?>—<?php endif;?></td><td><?=date_id($b['returned_at'],true)?></td><td><?=member_borrowing_badge($b['status'])?></td></tr><?php endforeach;?><?php if(!$borrowings):?><tr><td colspan="5">Belum ada riwayat peminjaman.</td></tr><?php endif;?></tbody></table></div></section>
<section class="member-section"><h2>Aduan terkirim</h2><?php foreach($complaints as $c):?><article class="history-item"><b><?=e($c['title'])?> · <?=e(ucfirst($c['type']))?></b><p><?=e($c['description'])?></p><small><?=date_id($c['created_at'],true)?> · Status: <?=e($c['status'])?><?= $c['admin_note']?' · Respon admin: '.e($c['admin_note']):' · Menunggu admin merespon'?></small></article><?php endforeach;?><?php if(!$complaints):?><p>Belum ada aduan.</p><?php endif;?></section>
<section class="member-section"><h2>Ajuan perpanjangan</h2><?php foreach($extensions as $x):?><article class="history-item"><b><?=e($x['title'])?> · <?= (int)$x['duration_days'] ?> hari</b><p><?=e($x['reason']??'')?></p><small><?=date_id($x['requested_at'],true)?> · <?=e($x['status'])?><?= $x['admin_note']?' · Catatan admin: '.e($x['admin_note']):''?></small></article><?php endforeach;?><?php if(!$extensions):?><p>Belum ada ajuan perpanjangan.</p><?php endif;?></section>
<section class="member-section"><h2>Review terkirim</h2><?php foreach($reviews as $r):?><article class="history-item"><b><?=e($r['title'])?> · <?=str_repeat('★',(int)$r['rating'])?></b><p><?=e($r['review'])?></p><small><?=date_id($r['created_at'],true)?></small></article><?php endforeach;?><?php if(!$reviews):?><p>Belum ada review.</p><?php endif;?></section><?php member_end(); ?>
